}if($v['rak_id']!==null&&!validArchiveLocation($pdo,$unit,$v['rak_id']))$errors[]='Rak tidak berada pada unit kerja Petugas.';
$s=$pdo->prepare('SELECT arsip_id FROM arsip WHERE no_registrasi=:n AND arsip_id!=:id');
$s->execute(['n'=>$v['no_registrasi'],'id'=>$id]);
if($s->fetch())$errors[]='Nomor registrasi sudah digunakan.';
if(!$errors&&$a==='create'){$pdo->beginTransaction();
try{$sql='INSERT INTO arsip(unit_id,jenis_surat_id,klasifikasi_id,rak_id,no_registrasi,no_surat,perihal,tanggal_surat,masa_simpan_tahun,tanggal_mulai_retensi,tanggal_jatuh_tempo,status_arsip,detail_arsip,keterangan,created_by) VALUES(:unit_id,:jenis_surat_id,:klasifikasi_id,:rak_id,:no_registrasi,:no_surat,:perihal,:tanggal_surat,:masa_simpan_tahun,:tanggal_mulai_retensi,:tanggal_jatuh_tempo,:status_arsip,:detail_arsip,:keterangan,:created_by)';
$pdo->prepare($sql)->execute($v+['unit_id'=>$unit,'created_by'=>(int)$_SESSION['user_id']]);
$newId=(int)$pdo->lastInsertId();
$pdo->prepare('INSERT INTO riwayat_arsip(arsip_id,user_id,aksi,keterangan) VALUES(:a,:u,\'CREATE\',\'Arsip dibuat\')')->execute(['a'=>$newId,'u'=>(int)$_SESSION['user_id']]);
$pdo->commit();
header('Location: arsip.php?edit='.$newId);
exit;
}catch(Throwable $e){$pdo->rollBack();
$errors[]='Data gagal disimpan. Silakan coba lagi.';
}}if(!$errors&&$a==='update'&&$id){$s=$pdo->prepare('UPDATE arsip SET jenis_surat_id=:jenis_surat_id,klasifikasi_id=:klasifikasi_id,rak_id=:rak_id,no_surat=:no_surat,perihal=:perihal,tanggal_surat=:tanggal_surat,masa_simpan_tahun=:masa_simpan_tahun,tanggal_mulai_retensi=:tanggal_mulai_retensi,tanggal_jatuh_tempo=:tanggal_jatuh_tempo,status_arsip=:status_arsip,detail_arsip=:detail_arsip,keterangan=:keterangan WHERE arsip_id=:id AND unit_id=:unit');
$s->execute($v+['id'=>$id,'unit'=>$unit]);
if(!$s->rowCount()){$errors[]='Arsip tidak ditemukan atau di luar unit kerja.';
}else{$pdo->prepare('INSERT INTO riwayat_arsip(arsip_id,user_id,aksi,keterangan) VALUES(:a,:u,\'UPDATE\',\'Arsip diperbarui\')')->execute(['a'=>$id,'u'=>(int)$_SESSION['user_id']]);
$notice='Arsip berhasil diperbarui.';
}}}}}if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM arsip WHERE arsip_id=:id AND unit_id=:unit');
