$edit=$s->fetch();
if(!$edit){http_response_code(403);
exit('Arsip tidak dapat diakses.');
}}$jenis=$pdo->query('SELECT jenis_surat_id,nama_jenis FROM jenis_surat ORDER BY nama_jenis')->fetchAll();
$klas=$pdo->query('SELECT klasifikasi_id,kode_klasifikasi,nama_klasifikasi FROM klasifikasi_arsip ORDER BY kode_klasifikasi')->fetchAll();
$s=$pdo->prepare('SELECT nama_unit FROM unit_kerja WHERE unit_id=:u');
$s->execute(['u'=>$unit]);
$unitName=(string)$s->fetchColumn();
$s=$pdo->prepare('SELECT r.ruangan_id,r.nama_ruangan,l.lemari_id,COALESCE(l.nama_lemari,l.kode_lemari) nama_lemari,k.rak_id,k.kode_rak FROM ruangan r JOIN lemari l ON l.ruangan_id=r.ruangan_id JOIN rak k ON k.lemari_id=l.lemari_id WHERE r.unit_id=:u ORDER BY r.nama_ruangan,l.kode_lemari,k.kode_rak');
$s->execute(['u'=>$unit]);
$locations=$s->fetchAll();
$selectedRoom=0;
$selectedCabinet=0;
$selectedRack=(int)($edit['rak_id']??0);
$lastRoom=0;
$lastCabinet=0;
foreach($locations as $location){if((int)$location['rak_id']===$selectedRack){$selectedRoom=(int)$location['ruangan_id'];$selectedCabinet=(int)$location['lemari_id'];break;}}
$q=trim((string)($_GET['q']??''));
$s=$pdo->prepare('SELECT a.*,j.nama_jenis,k.nama_klasifikasi FROM arsip a JOIN jenis_surat j ON j.jenis_surat_id=a.jenis_surat_id LEFT JOIN klasifikasi_arsip k ON k.klasifikasi_id=a.klasifikasi_id WHERE a.unit_id=:u AND (a.no_registrasi LIKE :q1 OR a.no_surat LIKE :q2 OR a.perihal LIKE :q3) ORDER BY a.created_at DESC');
$s->execute(['u'=>$unit,'q1'=>"%$q%",'q2'=>"%$q%",'q3'=>"%$q%"]);
$items=$s->fetchAll();
?>
