?></tbody></table></div></section><div id="detail-modal" hidden style="position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:1000;padding:2rem;overflow:auto"><section role="dialog" aria-modal="true" aria-label="Detail Arsip" style="background:#fff;margin:auto;max-width:960px;min-height:80vh;position:relative"><button id="detail-close" type="button" aria-label="Tutup" style="position:absolute;right:.75rem;top:.75rem;z-index:1">×</button><iframe id="detail-frame" title="Detail Arsip" style="border:0;width:100%;min-height:80vh"></iframe></section></div></main></div><script>const modal=document.getElementById('detail-modal'),frame=document.getElementById('detail-frame'),closeModal=()=>{modal.hidden=true;frame.removeAttribute('src');};document.querySelectorAll('.detail-link').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();frame.src=link.href;modal.hidden=false;}));document.getElementById('detail-close').onclick=closeModal;modal.onclick=event=>{if(event.target===modal)closeModal();};document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)closeModal();});const room=document.getElementById('ruangan_id'),cabinet=document.getElementById('lemari_id'),rack=document.getElementById('rak_id');function filter(select,key,value){for(const option of select.options)if(option.value)option.hidden=option.dataset[key]!==value;}function rooms(){filter(cabinet,'room',room.value);if(cabinet.selectedOptions[0]?.hidden)cabinet.value='';cabinets();}function cabinets(){filter(rack,'cabinet',cabinet.value);if(rack.selectedOptions[0]?.hidden)rack.value='';}room.onchange=rooms;cabinet.onchange=cabinets;rooms();</script></body></html>